(() => {
  'use strict';

  const moduleNames = {
    core: 'Основа / сервисы', player: 'Игрок / взаимодействие', inventory: 'Предметы / инвентарь',
    farm: 'Ферма', economy: 'Магазин / экономика / тележка', mailorders: 'Почта / заказы',
    storage: 'Хранилище', ui: 'UI / HUD', data: 'Данные / ScriptableObject', events: 'События / структуры данных',
    test: 'Временные тесты', legacy: 'Старая кодовая база'
  };

  const scripts = [
    {name:'GameServices', type:'MonoBehaviour · реестр', module:'core', path:'Assets/_Game/Scripts/Core/GameServices.cs', summary:'Единая точка, через которую система находит зарегистрированные сервисы. Он хранит ссылки, но не управляет балансом, днями или инвентарём.', where:'На одном объекте GameSystems в каждой игровой сцене. Не ставить на игрока и не создавать второй экземпляр.', must:'GameSystems; все сервисы, к которым нужен глобальный доступ, должны быть активны и вызывать Register(this).', optional:'Другие системы обращаются через GameServices.Instance.TryGet<T>(). Это не заменяет обычные ссылки, когда у объекта есть конкретная цель (например, камера и игрок).', methods:[['Awake()','Проверяет, что в сцене не появился второй GameServices.'],['Register<T>(service)','Добавляет экземпляр сервиса в реестр по его типу.'],['Unregister<T>(service)','Убирает сервис из реестра, когда компонент выключается.'],['TryGet<T>(out service)','Безопасно пытается найти сервис; возвращает false, если его нет.'],['OnDestroy()','Очищает статическую ссылку при уничтожении объекта.'],['ResetStatics()','Сбрасывает static-состояние перед новым запуском Play Mode.']], events:'Сам события не публикует; предоставляет доступ к WalletService, InventoryService, DayCycleService, ShopService, CartService, MailboxService и DailyOrderService.', note:'В сцене должен быть только один активный экземпляр. GameServices — реестр, не «бог-объект» с правилами игры.'},
    {name:'GameEvents', type:'static class · шина', module:'events', path:'Assets/_Game/Scripts/Core/GameEvents.cs', summary:'Общий канал сообщений. Отправитель публикует факт, а все подписчики, которым это важно, реагируют. Это уменьшает прямые связи между системами.', where:'Не добавляется в Hierarchy — это статический класс.', must:'Сам файл GameEvents.cs и определения типов событий, которые отправляются через него.', optional:'Любой MonoBehaviour может подписаться на событие и снять подписку при выключении.', methods:[['Subscribe<T>(callback)','Подписывает обработчик на события типа T.'],['Unsubscribe<T>(callback)','Отписывает обработчик; вызывай в OnDisable.'],['Publish<T>(message)','Рассылает событие подписчикам и запоминает последний payload этого типа.'],['TryGetLatest<T>(out message)','Возвращает последнее опубликованное событие, например начальный баланс или день.'],['Reset()','Очищает подписки и сохранённые последние события при перезапуске.']], events:'Ключевые типы: WalletBalanceEvent, DayChangedEvent, InventoryLayoutChangedEvent, CartStateChangedEvent, ShopTransactionRequestedEvent, ShopTransactionEvent, MailReadEvent, DailyOrdersChangedEvent, StorageOpenedEvent и HUDTextUpdateEvent.', note:'Для каждого OnEnable с Subscribe должен быть OnDisable с соответствующим Unsubscribe. Не создавай отдельную шину на каждую систему.'},
    {name:'GameplayInputGate', type:'static class · блокировка ввода', module:'core', path:'Assets/_Game/Scripts/Core/GameplayInputGate.cs', summary:'Глобальный флажок «игрок сейчас не управляется». Панель магазина, почты или хранилища блокирует управление, а при закрытии разрешает снова.', where:'Не добавляется в Hierarchy.', must:'В PlayerController2D, PlayerInteractor, InventorySelectionController и PlayerItemDropController должна быть проверка IsBlocked.', optional:'Используется панелями, которые временно захватывают управление.', methods:[['IsBlocked','Текущее состояние блокировки.'],['SetBlocked(bool)','Включает или снимает блокировку.'],['Reset()','Сбрасывает флаг перед новым запуском Play Mode.']], events:'Событий не публикует.', note:'Убедись, что Close/Read снимает блокировку. Не забывай сбрасывать её при отключении UI-компонента.'},
    {name:'DayCycleService', type:'MonoBehaviour · игровой календарь', module:'core', path:'Assets/_Game/Scripts/Core/DayCycleService.cs', summary:'Хранит номер текущего дня и отправляет событие при переходе на следующий день. Не знает, как растут растения или как обновляется HUD.', where:'На GameSystems.', must:'GameServices, GameEvents, активный объект GameSystems.', optional:'FarmCropSystem и DailyOrderService слушают DayChangedEvent; HUDDisplayBridge показывает текущий день.', methods:[['Awake()','Устанавливает Starting Day, обычно 1.'],['OnEnable()','Регистрируется в GameServices и публикует начальный день.'],['OnDisable()','Снимает регистрацию.'],['AdvanceDay()','Увеличивает CurrentDay и публикует DayChangedEvent.'],['PublishDay()','Создаёт событие DayChangedEvent с текущим номером.']], events:'Публикует DayChangedEvent. Слушатели: ферма, заказы, HUD.', note:'Временный DayAdvanceTest используется только для проверок. Позже смену дня должен запускать реальный игровой процесс.'},
    {name:'WalletService', type:'MonoBehaviour · деньги', module:'core', path:'Assets/_Game/Scripts/Economy/WalletService.cs', summary:'Хранит баланс игрока. Покупка списывает деньги, продажа и выполненный заказ начисляют их. UI не управляет балансом напрямую.', where:'На GameSystems.', must:'GameServices и GameEvents.', optional:'ShopService и DailyOrderService получают WalletService через GameServices; HUDDisplayBridge слушает WalletBalanceEvent.', methods:[['Awake()','Устанавливает Starting Balance.'],['OnEnable()','Регистрирует сервис и публикует начальный баланс.'],['OnDisable()','Удаляет регистрацию.'],['AddMoney(amount)','Добавляет положительную сумму и сообщает об изменении.'],['TrySpend(amount)','Списывает сумму только если баланс достаточен; возвращает успех/неудачу.'],['PublishBalance()','Публикует WalletBalanceEvent.']], events:'Публикует WalletBalanceEvent при старте, начислении и расходовании денег.', note:'Покупки и продажи должны идти через сервисы экономики — не меняй balance из UI.'},
    {name:'WalletBalanceEvent', type:'readonly struct · событие', module:'events', path:'Assets/_Game/Scripts/Core/GameEvents.cs (или файл событий в проекте)', summary:'Сообщение с новым балансом. HUD использует его для текста Money: N.', where:'Сам по себе в сцену не добавляется.', must:'WalletService публикует его; HUDDisplayBridge подписывается на него.', optional:'Другие UI-панели могут подписаться для отображения баланса.', methods:[['WalletBalanceEvent(int balance)','Создаёт сообщение с новым балансом.'],['Balance','Содержит опубликованный баланс.']], events:'Публикуется через GameEvents.', note:'Тип события должен существовать в проекте ровно в одном месте.'},
    {name:'DayChangedEvent', type:'readonly struct · событие', module:'events', path:'Assets/_Game/Scripts/Core/GameEvents.cs (или файл событий в проекте)', summary:'Факт, что игровой день изменился. Содержит номер нового дня.', where:'Не добавляется на GameObject.', must:'DayCycleService публикует событие.', optional:'Ферма, заказы и HUD могут на него подписываться.', methods:[['DayChangedEvent(int day)','Создаёт событие нового дня.'],['Day','Номер дня после перехода.']], events:'Подписчики: FarmCropSystem, DailyOrderService, HUDDisplayBridge.', note:'Смена дня не должна дублироваться внутри каждой игровой системы.'},
    {name:'PlayerController2D', type:'MonoBehaviour · движение', module:'player', path:'Assets/_Game/Scripts/Player/PlayerController2D.cs', summary:'Двигает Rigidbody2D, хранит направление действия и зеркалит спрайт влево/вправо. При запряжённой тележке использует меньшую скорость.', where:'На PF_Player вместе с Rigidbody2D.', must:'Rigidbody2D, SpriteRenderer в самом игроке или дочернем объекте, IDirectionalInteractor; Freeze Rotation Z и Gravity Scale 0 для top-down игры.', optional:'Слушает CartStateChangedEvent; GameplayInputGate останавливает движение при открытых окнах.', methods:[['Awake()','Получает Rigidbody2D и SpriteRenderer.'],['OnEnable()/OnDisable()','Подписывается/отписывается на состояние тележки.'],['OnCartStateChanged(event)','Запоминает, запряжена ли тележка.'],['Update()','Читает WASD/стрелки, обновляет movement и FacingDirection; зеркалит спрайт.'],['FixedUpdate()','Двигает Rigidbody2D через MovePosition с учётом cartSpeedMultiplier.']], events:'Слушает CartStateChangedEvent; читает GameplayInputGate.IsBlocked.', note:'Не вращает персонажа. При диагональном движении игрок идёт по диагонали, а FacingDirection выбирает одну сторону для взаимодействия.'},
    {name:'PlayerInteractor', type:'MonoBehaviour · поиск объектов', module:'player', path:'Assets/_Game/Scripts/Interaction/PlayerInteractor.cs', summary:'По Space ищет ближайший IInteractable в радиусе вокруг InteractionPoint и передаёт ему объект игрока.', where:'На PF_Player.', must:'Collider2D у объектов взаимодействия; InteractionPoint — дочерний Transform около ног; подходящий Interaction Radius.', optional:'FarmTilemapController, ShopStation, MailboxStation, StorageStation и SalesSourceStation реализуют IInteractable.', methods:[['Update()','Проверяет Space, собирает OverlapCircleAll и выбирает ближайшую цель.'],['OnDrawGizmosSelected()','Рисует круг радиуса взаимодействия в редакторе.'],['InteractionPosition','Возвращает позицию InteractionPoint; если ссылка пустая, использует позицию игрока.']], events:'Вызывает Interact(gameObject) у ближайшей цели. Учитывает GameplayInputGate.', note:'Не добавляй отдельный интерактор на каждое здание. Новому объекту достаточно Collider2D + IInteractable.'},
    {name:'IInteractable', type:'interface · договор взаимодействия', module:'player', path:'Assets/_Game/Scripts/Interaction/IInteractable.cs', summary:'Общий контракт для объекта, с которым игрок может взаимодействовать. Игроку не нужно знать, магазин это, почта или грядка.', where:'Не добавляется как компонент; класс реализуют станции и ферма.', must:'Реализующий компонент должен содержать Interact(GameObject interactor).', optional:'PlayerInteractor находит любой MonoBehaviour, реализующий интерфейс.', methods:[['Interact(GameObject interactor)','Единственный метод: выполнить действие при взаимодействии с игроком.']], events:'Отдельных событий нет; реализация может отправлять GameEvents.', note:'Не делай giant TriggerController. Каждая станция должна отвечать за своё действие.'},
    {name:'IDirectionalInteractor', type:'interface · направление игрока', module:'player', path:'Assets/_Game/Scripts/Interaction/IDirectionalInteractor.cs', summary:'Позволяет системам узнать последнее направление действия, не привязываясь к PlayerController2D напрямую.', where:'Не добавляется; реализуется PlayerController2D.', must:'Свойство FacingDirection типа Vector2.', optional:'FarmTilemapController использует его для определения клетки перед персонажем.', methods:[['FacingDirection','Последнее кардинальное направление игрока: вверх, вниз, влево или вправо.']], events:'Нет.', note:'Это маленький интерфейс, который помогает не смешивать выбор направления и механику фермы.'},
    {name:'CameraFollow2D', type:'MonoBehaviour · камера', module:'player', path:'Assets/_Game/Scripts/Player/CameraFollow2D.cs', summary:'Плавно перемещает камеру за игроком без вращения.', where:'На Main Camera.', must:'Camera в режиме Orthographic; поле Target указывает на Transform игрока; Offset по Z обычно -10.', optional:'Smooth Time и Offset настраиваются в Inspector.', methods:[['LateUpdate()','После движения игрока плавно перемещает камеру через SmoothDamp.']], events:'Не связан с GameEvents.', note:'Это один из немногих случаев, когда явная ссылка в Inspector правильна: камера должна знать конкретную цель.'},
    {name:'InventorySelectionController', type:'MonoBehaviour · выбор слота', module:'player', path:'Assets/_Game/Scripts/Player/InventorySelectionController.cs', summary:'Выбирает слот клавишами 1–9 / NumPad и колесом мыши.', where:'На PF_Player.', must:'GameServices и InventoryService должны быть доступны.', optional:'GameplayInputGate блокирует ввод, пока открыта панель.', methods:[['Update()','Сначала проверяет блокировку, затем клавиши/колесо и вызывает SelectSlot или SelectNextAccessibleSlot.']], events:'InventoryService публикует обновление раскладки; HUD подсвечивает выбранную карточку.', note:'Слоты Cart недоступны, когда тележка припаркована; переключение пропускает закрытые слоты.'},
    {name:'PlayerItemDropController', type:'MonoBehaviour · выброс предмета', module:'player', path:'Assets/_Game/Scripts/Player/PlayerItemDropController.cs', summary:'На Q убирает всю стопку из активного слота и создаёт в мире её индивидуальный prefab.', where:'На PF_Player.', must:'InventoryService через GameServices; у ItemDefinition должен быть назначен WorldPrefab; в Player есть направление.', optional:'dropDistance в Inspector регулирует, как далеко перед игроком появится предмет.', methods:[['Awake()','Получает IDirectionalInteractor.'],['Update()','Реагирует на Q, если ввод не заблокирован.'],['DropSelectedItem()','Проверяет prefab, удаляет содержимое выбранного слота и создаёт pickup в мире.']], events:'Инвентарь публикует новое состояние автоматически после удаления.', note:'У каждого предмета может быть свой prefab и свой масштаб — не подменяй его универсальным prefab, если внешний вид отличается.'},
    {name:'InventoryService', type:'MonoBehaviour · модель инвентаря', module:'inventory', path:'Assets/_Game/Scripts/Items/InventoryService.cs', summary:'Главное хранилище игрока. Управляет стопками, добавлением/удалением, выбором, перестановкой и секциями Base / Backpack / Cart.', where:'На PF_Player. Базовая вместимость — 2 слота.', must:'GameServices; CartStateChangedEvent; ItemDefinition; enum InventorySlotGroup; событие InventoryLayoutChangedEvent.', optional:'ShopService добавляет бонусы, PickupItem поднимает вещи, StoragePanelController переносит предметы, HUD рисует карточки.', methods:[['Awake()','Создаёт базовые слоты и пересчитывает раскладку.'],['OnEnable()/OnDisable()','Регистрируется в GameServices и слушает состояние тележки.'],['SetCapacityBonus(sourceId, extraSlots, group)','Добавляет/снимает слоты с источником и группой (Backpack или Cart). Не удаляет предметы, если слоты заняты.'],['SelectSlot(index)','Выбирает доступный слот.'],['SwapSlots(firstIndex, secondIndex)','Меняет содержимое доступных слотов, сами группы слотов не перемещаются.'],['SelectNextAccessibleSlot(direction)','Переключает на следующий доступный слот.'],['TryRemoveSelectedSlot(out item, out quantity)','Забирает целую стопку активного слота для выбрасывания.'],['TryGetSlotContents / CanAcceptAtSlot','Проверяет содержимое/вместимость конкретного слота.'],['TryAddToSlot / TryTakeFromSlot','Добавляет или забирает предмет из заданного слота; используется в переносах.'],['AddItem(item, amount)','Сначала заполняет неполные стопки, затем пустые слоты; возвращает остаток.'],['GetAvailableSpace(item)','Сколько ещё единиц можно поместить с учётом MaxStackSize.'],['GetItemCount / HasItem / RemoveItem','Считает, проверяет наличие или удаляет указанное количество.'],['PublishChanged()','Публикует полный снимок слотов и выбранный индекс.']], events:'Публикует InventoryLayoutChangedEvent. Слушает CartStateChangedEvent. Обновление UI происходит через события, а не прямую ссылку из HUD.', note:'Слоты группируются в Base, Backpack и Cart. При припаркованной тележке её содержимое остаётся, но слот недоступен. Не меняй Capacity напрямую.'},
    {name:'InventorySlot', type:'класс данных', module:'inventory', path:'Assets/_Game/Scripts/Items/InventoryService.cs', summary:'Одна ячейка инвентаря: предмет, количество и группа.', where:'Создаётся InventoryService автоматически.', must:'ItemDefinition и InventorySlotGroup.', optional:'Не добавляется в Hierarchy.', methods:[['Set(item, quantity)','Записывает содержимое слота.'],['Clear()','Делает слот пустым.'],['IsEmpty','Проверяет, пуст слот или нет.']], events:'Нет.', note:'UI не должен самостоятельно менять поля слота — изменения идут через InventoryService.'},
    {name:'InventorySlotGroup', type:'enum · группа слотов', module:'events', path:'Assets/_Game/Scripts/Core/InventorySlotGroup.cs', summary:'Отмечает, откуда появилась вместимость: обычная, рюкзак или тележка.', where:'Не добавляется на объекты; хранится у каждого слота.', must:'Значения Base, Backpack, Cart.', optional:'HUD показывает название секции, InventoryService определяет доступность Cart.', methods:[['Base','Два исходных слота.'],['Backpack','Слоты, добавленные рюкзаком.'],['Cart','Слоты, добавленные тележкой.']], events:'Используется в InventoryLayoutChangedEvent.', note:'При обмене предметами меняется содержимое, но не группа слота.'},
    {name:'InventorySlotDisplayData', type:'readonly struct · снимок слота', module:'events', path:'Assets/_Game/Scripts/Core/InventoryLayoutChangedEvent.cs', summary:'Безопасное представление слота для интерфейса: предмет, количество, группа и доступность.', where:'Создаётся InventoryService при публикации обновления раскладки.', must:'ItemDefinition, InventorySlotGroup.', optional:'Используется InventoryHUDController и HUDDisplayBridge.', methods:[['InventorySlotDisplayData(...)','Создаёт снимок одного слота.'],['IsEmpty','Проверяет, есть ли предмет и количество.']], events:'Входит в массив InventoryLayoutChangedEvent.', note:'Это копия данных для UI, а не сама изменяемая ячейка.'},
    {name:'InventoryLayoutChangedEvent', type:'readonly struct · событие раскладки', module:'events', path:'Assets/_Game/Scripts/Core/InventoryLayoutChangedEvent.cs', summary:'Содержит актуальный массив карточек и выбранный индекс после любого изменения инвентаря.', where:'Публикуется InventoryService.', must:'InventorySlotDisplayData[] Slots, SelectedSlotIndex.', optional:'InventoryHUDController и HUDDisplayBridge подписываются на него.', methods:[['InventoryLayoutChangedEvent(slots, selectedIndex)','Создаёт полный снимок раскладки.']], events:'GameEvents.Publish / Subscribe.', note:'Используется более поздней системой карточек; не путай со старой InventoryChangedEvent из раннего прототипа.'},
    {name:'CartStateChangedEvent', type:'readonly struct · состояние тележки', module:'events', path:'Assets/_Game/Scripts/Core/CartStateChangedEvent.cs', summary:'Сообщает, куплена ли тележка и запряжена ли она сейчас.', where:'Публикуется CartService.', must:'HasCart и IsHitched.', optional:'InventoryService блокирует Cart-слоты, PlayerController2D меняет скорость, HUD обновляет карточки.', methods:[['CartStateChangedEvent(hasCart, isHitched)','Создаёт событие; IsHitched false, если тележки нет.']], events:'GameEvents.', note:'При парковке предметы не исчезают — меняется только доступность тележки.'},
    {name:'InventorySlotCardView', type:'MonoBehaviour · карточка инвентаря', module:'ui', path:'Assets/_Game/Scripts/UI/InventorySlotCardView.cs', summary:'Визуальная карточка одного слота: иконка, название, количество/лимит, выбранное состояние и Drag & Drop.', where:'На корневом объекте PF_InventorySlotCard.', must:'Image, TMP labels, LayoutElement; InventoryHUDController назначает данные через Bind(); активный EventSystem и Canvas GraphicRaycaster.', optional:'Иконка из ItemDefinition.Icon может быть пустой.', methods:[['Awake()','Получает компоненты карточки.'],['Bind(...)','Заполняет индекс, предмет, количество, группу, доступность, подсветку и ссылки на Canvas/контроллер.'],['OnPointerClick()','Выбирает слот.'],['OnBeginDrag / OnDrag / OnEndDrag','Создаёт и двигает призрак предмета, завершает перетаскивание.'],['OnDrop()','Просит InventoryHUDController поменять содержимое двух слотов.'],['UpdateGhostPosition()','Обновляет позицию значка при переносе.'],['OnDisable()','Очищает временный drag ghost.']], events:'Вызывает SelectSlot/SwapSlots у InventoryHUDController; тот работает с InventoryService через GameServices.', note:'Поля Image и TMP назначаются в prefab один раз. Raycast Target обычно оставляют на корневом Image карточки.'},
    {name:'InventoryHUDController', type:'MonoBehaviour · список карточек игрока', module:'ui', path:'Assets/_Game/Scripts/UI/InventoryHUDController.cs', summary:'Слушает раскладку инвентаря, создаёт правильное число карточек и обрабатывает выбор/обмен.', where:'На InventoryBar в GameHUD, не на каждой карточке.', must:'Card Root = Content; Card Prefab = PF_InventorySlotCard; Canvas; ScrollRect; Content с Horizontal Layout Group / Content Size Fitter; EventSystem.', optional:'Прячет карточки Cart, когда тележка припаркована (в текущей настройке проекта).', methods:[['Awake()','Находит root Canvas и проверяет настройки.'],['OnEnable()/OnDisable()','Подписывается на InventoryLayoutChangedEvent.'],['Start()/RefreshLatest()','Подхватывает последнее состояние, если сервис опубликовал его позже.'],['OnInventoryChanged(event)','Создаёт/обновляет карточки, назначает группу и selected marker.'],['EnsureCardCount(count)','Создаёт или удаляет карточки до нужного количества.'],['SelectSlot(index)','Передаёт выбор InventoryService.'],['SwapSlots(source, target)','Передаёт запрос на обмен и блокирует недоступные Cart-слоты.']], events:'Слушает InventoryLayoutChangedEvent; использует GameServices и GameplayInputGate.', note:'Старый InventoryContentsText нужно отключить, если отображаются карточки — иначе инвентарь дублируется.'},
    {name:'ItemDefinition', type:'ScriptableObject · описание предмета', module:'data', path:'Assets/_Game/Scripts/Items/ItemDefinition.cs', summary:'Данные предмета: ID, английское имя, описание, иконка, MaxStackSize и prefab для отображения в мире.', where:'Ассеты в Assets/_Game/Data/Items/. Создаётся через Create → Game → Items → Item Definition.', must:'Уникальный Item Id, Display Name, Max Stack Size.', optional:'Icon для UI. WorldPrefab для pickup и выбрасывания. WorldPrefab сохраняет исходный масштаб предмета.', methods:[['CreateAssetMenu','Добавляет пункт создания ассета в Project.'],['ItemId / DisplayName / Description','Свойства данных предмета.'],['Icon','Спрайт карточки UI (может отсутствовать).'],['MaxStackSize','Максимум единиц в одной стопке.'],['WorldPrefab','Конкретный PickupItem prefab для этого предмета.']], events:'Используется инвентарём, магазином, заказами, фермерством и хранилищем.', note:'Механику предмета не нужно хранить здесь: это данные, а не MonoBehaviour.'},
    {name:'PickupItem', type:'MonoBehaviour · предмет в мире', module:'inventory', path:'Assets/_Game/Scripts/Items/PickupItem.cs', summary:'Позволяет подобрать предмет через Space. При частичном добавлении оставляет непоместившуюся часть в мире.', where:'На каждом pickup-префабе предмета.', must:'Collider2D; ItemDefinition; реализация IInteractable. Сам объект/родитель должен находиться в радиусе PlayerInteractor.', optional:'WorldItemPulse для анимации; спрайт/масштаб/коллайдер задаются в индивидуальном prefab.', methods:[['Awake()','Получает визуальные компоненты, если это предусмотрено текущей версией.'],['Initialize(definition, quantity)','Настраивает содержимое созданного объекта при выбрасывании.'],['Interact(interactor)','Находит InventoryService, добавляет предмет и уничтожает объект только после полного подбора.']], events:'Изменение инвентаря публикуется InventoryService.', note:'Для каждого ItemDefinition назначь WorldPrefab. Если prefab не назначен, PlayerItemDropController не должен удалять предмет из инвентаря.'},
    {name:'WorldItemPulse', type:'MonoBehaviour · анимация предмета', module:'inventory', path:'Assets/_Game/Scripts/Items/WorldItemPulse.cs', summary:'Пульсирует масштабом предмета на земле, возвращая его к исходному значению и не меняя позицию.', where:'На SpriteRenderer-объекте каждого pickup prefab.', must:'Начальный Transform Scale, который задаёт нужный размер предмета.', optional:'Scale Amount и Cycles Per Second в Inspector.', methods:[['Awake()','Запоминает исходный масштаб.'],['Update()','Вычисляет синусоидальный коэффициент масштаба.']], events:'Нет.', note:'Масштаб предметов индивидуальный и хранится в prefab, поэтому выкинутая лейка не должна становиться размером с тыкву.'},
    {name:'CartService', type:'MonoBehaviour · владение тележкой', module:'economy', path:'Assets/_Game/Scripts/Core/CartService.cs', summary:'Создаёт купленную тележку, добавляет Cart-слоты и обрабатывает G: отцепить или запрячь рядом с игроком.', where:'На GameSystems.', must:'Cart Prefab назначен; InventoryService; GameServices; CartStateChangedEvent.', optional:'Follow Distance, Hitch Range и Toggle Key настраиваются в Inspector.', methods:[['OnEnable()/OnDisable()','Регистрируется и при выключении публикует припаркованное состояние.'],['Update()','По G переключает тележку, если ввод не заблокирован.'],['TryActivate(productId, capacityBonus, inventory)','Создаёт тележку и добавляет слоты группы Cart.'],['ToggleCart()','Паркует или снова запрягает тележку, проверяя расстояние.']], events:'Публикует CartStateChangedEvent; ShopService вызывает TryActivate для покупки тележки.', note:'Контент Cart-слотов хранится в InventoryService. При парковке UI скрывает карточки Cart, предметы остаются.'},
    {name:'CartFollower', type:'MonoBehaviour · физический объект тележки', module:'economy', path:'Assets/_Game/Scripts/Core/CartFollower.cs', summary:'Плавно следует позади игрока в сторону, противоположную его последнему движению. Может быть припаркован.', where:'На PF_Cart.', must:'SpriteRenderer; CartService создаёт этот prefab и зовёт Initialize(owner, followDistance). Collider для базовой версии не нужен.', optional:'Smooth Time, Follow Distance и Position Offset.', methods:[['Initialize(followTarget, distance)','Запоминает игрока, рассчитывает начальную позицию и запрягает тележку.'],['SetHitched(bool)','Включает/выключает следование.'],['LateUpdate()','Плавно следует за целью через SmoothDamp.']], events:'Состояние наружу публикует CartService.', note:'Тележка останавливается на месте, если отцеплена; повторная G работает только в пределах Hitch Range.'},
    {name:'ShopProductDefinition', type:'ScriptableObject · товар магазина', module:'data', path:'Assets/_Game/Scripts/Shop/ShopProductDefinition.cs', summary:'Описывает, что продаёт магазин: обычный предмет, рюкзак или тележку; цены и бонус вместимости.', where:'Ассеты Assets/_Game/Data/Shop/. Create → Game → Shop → Product.', must:'Уникальный ProductId, тип продукта, цены, Can Buy/Can Sell.', optional:'Item нужен для обычных товаров, для BackpackUpgrade / CartUpgrade оставляется пустым; Capacity Bonus > 0 для апгрейдов.', methods:[['CreateAssetMenu','Создаёт ассет товара.'],['DisplayName','Название товара; берёт заданное название или имя предмета.'],['CanBuy / CanSell','Учитывают флаги и тип продукта.'],['ProductType','Item, BackpackUpgrade или CartUpgrade.'],['CapacityBonus','Количество слотов апгрейда.']], events:'Читается ShopCatalog и ShopService.', note:'Цена и логика покупки — разные вещи. Этот ассет хранит параметры, ShopService выполняет транзакцию.'},
    {name:'ShopCatalog', type:'ScriptableObject · список магазина', module:'data', path:'Assets/_Game/Scripts/Shop/ShopCatalog.cs', summary:'Содержит название магазина и список ShopProductDefinition, которые должны отображаться при открытии.', where:'Assets/_Game/Data/Shop/Catalog_*. Создать через Create → Game → Shop → Catalog.', must:'Display Name и массив Products.', optional:'Разные магазины могут ссылаться на разные каталоги.', methods:[['CreateAssetMenu','Добавляет создание каталога в Project.'],['DisplayName','Заголовок панели магазина.'],['Products','Массив товаров для генерации UI.']], events:'ShopStation публикует ShopOpenedEvent с нужным каталогом.', note:'Добавить товар в каталог — это настройка контента, а не переписывание ShopPanelController.'},
    {name:'ShopService', type:'MonoBehaviour · транзакции', module:'economy', path:'Assets/_Game/Scripts/Shop/ShopService.cs', summary:'Проверяет покупки/продажи, деньги, наличие предметов и место в инвентаре. Обрабатывает улучшения рюкзака и тележки.', where:'На GameSystems.', must:'GameServices, WalletService, InventoryService; для CartUpgrade также CartService; события ShopTransactionRequestedEvent и ShopTransactionEvent.', optional:'Новые товары добавляются ассетами, а не новыми методами покупки.', methods:[['OnEnable()/OnDisable()','Регистрируется и подписывается на запросы транзакций.'],['OnTransactionRequested(event)','Направляет событие на TryBuy или TrySell.'],['TryBuy(product, quantity)','Проверяет товар, цену и место; обрабатывает обычный предмет или апгрейд.'],['TryBuyBackpack(...)','Списывает деньги и добавляет слоты Backpack; не даёт купить дважды.'],['TryBuyCart(...)','Проверяет и активирует CartService; добавляет Cart-слоты.'],['TrySell(product, quantity)','Удаляет заданное количество предметов и начисляет деньги.'],['TryGetServices(...)','Получает InventoryService и WalletService из GameServices.'],['Fail / PublishResult','Публикует результат транзакции и пишет диагностическое сообщение.']], events:'Слушает ShopTransactionRequestedEvent; публикует ShopTransactionEvent. Меняет InventoryService/WalletService через их API.', note:'Флаг купленного улучшения хранится в памяти текущего запуска; постоянное сохранение ещё не подключено.'},
    {name:'ShopStation', type:'MonoBehaviour · точка открытия', module:'economy', path:'Assets/_Game/Scripts/Shop/ShopStation.cs', summary:'Открывает конкретный каталог при взаимодействии игрока.', where:'На здании/прилавке магазина.', must:'Collider2D и назначенный ShopCatalog.', optional:'SpriteRenderer здания.', methods:[['Interact(interactor)','Публикует ShopOpenedEvent с каталогом магазина.']], events:'ShopPanelController слушает ShopOpenedEvent.', note:'Для второго магазина можно использовать тот же скрипт и другой каталог.'},
    {name:'ShopProductRowView', type:'MonoBehaviour · строка каталога', module:'economy', path:'Assets/_Game/Scripts/Shop/ShopProductRowView.cs', summary:'Показывает название товара и кнопки Buy/Sell с ценами из ассета.', where:'На корне PF_ShopProductRow.', must:'Product Name (TMP), Buy Button, Sell Button; Scroll/Vertical Layout генерирует строки.', optional:'Тип товара может отключать кнопку продажи/покупки.', methods:[['Awake()','Подписывает кнопки на Buy и Sell.'],['OnDestroy()','Снимает слушателей кнопок.'],['Setup(definition)','Заполняет название, цены и доступность кнопок.'],['Buy()/Sell()','Публикует ShopTransactionRequestedEvent.']], events:'Публикует ShopTransactionRequestedEvent; получает результат через другие UI-слушатели.', note:'UI не списывает деньги сам — он только отправляет запрос.'},
    {name:'ShopPanelController', type:'MonoBehaviour · окно магазина', module:'ui', path:'Assets/_Game/Scripts/Shop/ShopPanelController.cs', summary:'Создаёт строки магазина из каталога и показывает результат операции. Пока открыта панель, игрок не управляется.', where:'На активном GameHUD, НЕ на выключаемом ShopPanel.', must:'Panel Root, Title TMP, Message TMP, Close Button, Product List Root, Row Prefab.', optional:'Product List Root с Vertical Layout Group; ScrollRect, если товаров много.', methods:[['OnEnable()/OnDisable()','Подписывается на ShopOpenedEvent и ShopTransactionEvent; привязывает кнопку Close.'],['Update()','Escape закрывает магазин только если эта версия контроллера поддерживает такое закрытие; в текущем согласованном поведении выход — через Close.'],['OnShopOpened(event)','Очищает старые строки, создаёт новые из каталога и открывает панель.'],['OnTransactionResult(event)','Показывает успешный результат или причину отказа.'],['Close()','Закрывает панель и снимает GameplayInputGate.'],['ClearRows()','Удаляет созданные runtime-строки.']], events:'Слушает ShopOpenedEvent и ShopTransactionEvent.', note:'Close должен оставаться доступным. Пока магазин открыт, движение и остальные действия игрока блокируются.'},
    {name:'ShopTransactionRequestedEvent', type:'readonly struct · запрос', module:'events', path:'Assets/_Game/Scripts/Shop/ShopTransactionRequestedEvent.cs или GameEvents.cs', summary:'Команда от UI: купить или продать выбранный товар и какое количество.', where:'Создаётся ShopProductRowView при клике.', must:'Product, Quantity, IsPurchase.', optional:'Новые UI могут публиковать тот же тип события.', methods:[['ShopTransactionRequestedEvent(product, quantity, isPurchase)','Создаёт запрос операции.']], events:'ShopService слушает запрос.', note:'Запрос не означает успех; ответ приходит через ShopTransactionEvent.'},
    {name:'ShopTransactionEvent', type:'readonly struct · результат', module:'events', path:'Assets/_Game/Scripts/Shop/ShopTransactionEvent.cs или GameEvents.cs', summary:'Содержит результат операции, ID товара и короткое сообщение для UI.', where:'Публикуется ShopService.', must:'Success, ProductId, Message.', optional:'ShopPanelController показывает сообщение.', methods:[['ShopTransactionEvent(success, productId, message)','Создаёт итог операции.']], events:'GameEvents.Publish.', note:'Игровой текст оставляем на английском; пояснения в техническом сайте — на русском.'},
    {name:'HUDTextBinding', type:'MonoBehaviour · ключ текста', module:'ui', path:'Assets/_Game/Scripts/UI/HUDTextBinding.cs', summary:'Привязывает TextMeshProUGUI к ключу из enum. На объекте не нужны ссылки на сервисы.', where:'На каждом TMP-тексте, который обновляет HUDPresenter.', must:'TextMeshProUGUI на том же GameObject; выбранный HUDTextKey в Inspector.', optional:'Ключи текущего проекта: WalletBalance, CurrentDay, OrderProgress, ActiveOrders; старые InventoryContents/MailNotification могут остаться, но текст MailNotification удалён из HUD.', methods:[['Awake()','Находит TMP label.'],['SetText(value)','Меняет отображаемую строку.'],['Key','Возвращает выбранный enum-ключ.']], events:'HUDPresenter находит bindings среди дочерних объектов GameHUD.', note:'Не печатай ключ строкой вручную. Используй dropdown, чтобы не ошибаться в написании.'},
    {name:'HUDPresenter', type:'MonoBehaviour · отрисовка текстовых значений', module:'ui', path:'Assets/_Game/Scripts/UI/HUDPresenter.cs', summary:'Слушает HUDTextUpdateEvent и обновляет компонент HUDTextBinding с совпадающим ключом.', where:'На GameHUD, остаётся активным независимо от открытых панелей.', must:'Дочерние HUDTextBinding с уникальными ключами.', optional:'HUDDisplayBridge отправляет текстовые обновления; по запросу может получить свежие данные через HUDRefreshRequestedEvent.', methods:[['Awake()/CacheBindings()','Находит дочерние HUDTextBinding и строит индекс по ключу.'],['OnEnable()/OnDisable()','Подписывается/отписывается на HUDTextUpdateEvent.'],['OnTextUpdated(event)','Ищет binding по HUDTextKey и записывает текст.']], events:'Слушает HUDTextUpdateEvent; может публиковать HUDRefreshRequestedEvent при включении.', note:'Не знает, как устроены кошелёк, заказы или ферма. Это принципиально.'},
    {name:'HUDDisplayBridge', type:'MonoBehaviour · перевод событий в HUD-текст', module:'ui', path:'Assets/_Game/Scripts/UI/HUDDisplayBridge.cs', summary:'Промежуточный слой: слушает игровые события и превращает их в обычные строки для HUDPresenter.', where:'На GameHUD.', must:'HUDPresenter + необходимые HUDTextBinding; GameEvents; события сервисов.', optional:'Некоторые старые ключи могут оставаться в enum, даже если их TMP-элемент выключен.', methods:[['OnEnable()/OnDisable()','Подписывается на WalletBalanceEvent, DayChangedEvent, InventoryLayoutChangedEvent, DailyOrdersChangedEvent и refresh-запрос.'],['OnWalletChanged(event)','Публикует текст Money: N.'],['OnDayChanged(event)','Публикует Day: N.'],['OnInventoryChanged(event)','Формирует текстовый список/статус слотов для старого Text HUD; карточный HUD работает параллельно отдельно.'],['OnDailyOrdersChanged(event)','Формирует OrderProgress и ActiveOrders; пока заказам не дали видимость, текст очищен/скрыт.'],['OnRefreshRequested(event)/RefreshLatest()','Повторно публикует последнее состояние для поздно активировавшихся панелей.'],['Publish(key, text)','Публикует HUDTextUpdateEvent.']], events:'Слушает события gameplay и публикует HUDTextUpdateEvent.', note:'Для активного инвентаря сейчас используется InventoryHUDController с карточками. Старый InventoryContentsText можно выключить, чтобы не дублировать карточки.'},
    {name:'HUDTextUpdateEvent', type:'readonly struct · UI-команда', module:'events', path:'Assets/_Game/Scripts/UI/HUDDisplayBridge.cs', summary:'Пара ключ + текст для HUD.', where:'Не добавляется на сцену.', must:'HUDTextKey Key и string Text.', optional:'HUDPresenter.', methods:[['HUDTextUpdateEvent(key, text)','Создаёт обновление одного текстового значения.']], events:'Публикуется HUDDisplayBridge, слушается HUDPresenter.', note:'Нужен только для простых текстовых значений, не для карточек с Drag & Drop.'},
    {name:'HUDRefreshRequestedEvent', type:'readonly struct · запрос обновления', module:'events', path:'Assets/_Game/Scripts/UI/HUDDisplayBridge.cs', summary:'Просит мост повторно выдать последние известные данные после включения UI.', where:'Публикуется UI при включении.', must:'Обработчик HUDDisplayBridge.', optional:'Позволяет поздно включённой панели не ждать следующего изменения баланса/дня.', methods:[['HUDRefreshRequestedEvent()','Пустое событие-запрос.']], events:'Слушается HUDDisplayBridge.', note:'Это запрос на refresh, а не новое игровое действие.'},
    {name:'WalletHUDView / WalletHUDAdapter', type:'устаревшая пара UI-скриптов', module:'legacy', path:'Assets/_Game/Scripts/UI/WalletHUDView.cs и WalletHUDAdapter.cs', summary:'Первая версия UI баланса, где адаптер напрямую подписывался на WalletService.', where:'Не добавлять на новую сцену; компоненты удалялись при переходе на HUDPresenter + HUDDisplayBridge.', must:'В текущей схеме не нужны.', optional:'Файлы могут всё ещё лежать на диске.', methods:[['SetBalance(balance)','Отображала баланс в TMP.'],['Connect/Refresh/Disconnect','Старая прямая подписка на WalletService.']], events:'Заменены текущей общей HUD-схемой.', note:'Если файлы остались, это не проблема; главное — не держать старый компонент на Canvas.'},
    {name:'InventoryHUDView / InventoryHUDAdapter', type:'устаревшая пара UI-скриптов', module:'legacy', path:'Assets/_Game/Scripts/UI/InventoryHUDView.cs и InventoryHUDAdapter.cs', summary:'Ранняя версия текстового инвентаря, где отдельный адаптер ссылался на InventoryService.', where:'Не добавлять на новую сцену; заменено InventoryHUDController + InventorySlotCardView.', must:'В текущей схеме не нужны.', optional:'Файлы могут остаться, если компоненты с объектов удалены.', methods:[['SetSlotText(index, text)','Старая View меняла текст слота.'],['Connect/Refresh/Disconnect','Старая прямая подписка на InventoryService.']], events:'Заменены событийной системой и карточками.', note:'Не добавлять вместе с карточным HUD — будет дублирование.'},
    {name:'Item / Crop / Shop ScriptableObjects', type:'группа данных', module:'data', path:'Assets/_Game/Data/', summary:'Контент, который дизайнер или разработчик может менять в Inspector, не переписывая логику.', where:'Project window: Data/Items, Data/Crops, Data/Shop, Data/Orders, Data/Carving.', must:'Все Item Id / Product Id / Source Id должны быть уникальны в рамках своего назначения.', optional:'Иконки и описания можно добавлять постепенно.', methods:[['ItemDefinition','Описание предмета, MaxStackSize, Icon и WorldPrefab.'],['CropDefinition','SeedItem, HarvestItem, HarvestAmount, GrowthSprites в правильном порядке и WitheredSprite.'],['ShopProductDefinition','Цена покупки/продажи, разрешения покупки/продажи, тип апгрейда и CapacityBonus.'],['ShopCatalog','Список товаров для одного магазина.'],['DemandSourceDefinition','Название бизнеса, шанс ежедневного заказа, варианты количества и награды.'],['CarvingRecipe','Описание входного предмета и результата; новый модуль вырезания пока отложен.']], events:'Читаются сервисами, но сами не публикуют событий.', note:'Изменение ассета влияет на все места, которые используют один и тот же ассет.'},
    {name:'CropDefinition', type:'ScriptableObject · культура', module:'data', path:'Assets/_Game/Scripts/Farming/CropDefinition.cs', summary:'Хранит семена, урожай, количество урожая, спрайты роста по порядку и спрайт увядания.', where:'Ассет в Assets/_Game/Data/Crops/, например Crop_Pumpkin.', must:'Seed Item, Harvest Item, минимум два Growth Sprites, все спрайты заполнены, Withered Sprite.', optional:'Для будущих культур создаётся свой asset; контроллер фермы общий.', methods:[['GetGrowthSprite(stage)','Возвращает спрайт указанной стадии, или null при неверном индексе.'],['GrowthStageCount','Количество стадий.'],['HasValidGrowthSprites','Проверяет массив стадий перед посадкой.']], events:'Использует ItemDefinition; читается FarmCropSystem.', note:'Последний спрайт массива — зрелая тыква. 4 спрайта означают 3 перехода дня после начальной стадии, если полив есть каждый день.'},
    {name:'FarmTilemapController', type:'MonoBehaviour · вход в ферму', module:'farm', path:'Assets/_Game/Scripts/Farming/FarmTilemapController.cs', summary:'Определяет клетку перед игроком, понимает выбранный предмет и направляет действие в FarmCropSystem. Не должен сам хранить всю историю роста.', where:'На FarmTilemap вместе с TilemapCollider2D и тремя Farm-компонентами.', must:'Tilemap, Tilled Tile, Available Crops, Player, Target Preview; FarmCropSystem, FarmTileVisuals, FarmTargetPreview на том же объекте; Collider2D на Tilemap.', optional:'WaterOverlayTilemap как соседний объект в Grid — нужен текущему FarmTileVisuals для затемнения воды.', methods:[['Awake()','Получает соседние компоненты и передаёт им настройки через Initialize.'],['Update()','Обновляет целевую подсветку.'],['Interact(interactor)','Выбирает клетку и направляет действия к TryTill / TryPlant / TryWater / TryHarvest / ClearWitheredCrop.'],['UpdateTargetPreview()','Показывает маркер, если выбранное действие допустимо.'],['CanInteractWithCell(cell)','Проверяет возможность выбранного действия для клетки.'],['TryGetInventory()','Получает InventoryService из GameServices.'],['GetInteractionPosition()','Использует InteractionPoint около ног игрока.'],['GetTargetCell()','Преобразует позицию и FacingDirection в соседнюю клетку.']], events:'Реализует IInteractable. Использует GameServices и вызывает FarmCropSystem / FarmTileVisuals / FarmTargetPreview.', note:'Это диспетчер взаимодействия, а не хранилище состояния растений.'},
    {name:'FarmCropSystem', type:'MonoBehaviour · правила растений', module:'farm', path:'Assets/_Game/Scripts/Farming/FarmCropSystem.cs', summary:'Хранит состояние каждой клетки: вспахана ли она, что посажено, текущая стадия, последний день полива, готовность и увядание.', where:'На том же FarmTilemap, что FarmTilemapController.', must:'Initialize вызывается контроллером; получает Tilemap, FarmTileVisuals и массив CropDefinition. Слушает DayChangedEvent.', optional:'Инвентарь и календарь находятся через GameServices, а не через прямые поля Inspector.', methods:[['Initialize(tilemap, visuals, crops)','Связывает ссылки, переданные контроллером.'],['HasCropAt / IsReady / IsWithered','Возвращают состояние клетки.'],['FindCropForSeed(item)','Находит CropDefinition по предмету семян.'],['CanTill / TryTill','Проверяет и вспахивает свободную клетку.'],['CanPlant / TryPlant','Проверяет почву, забирает семя и создаёт запись культуры.'],['CanWater / TryWater','Проверяет и отмечает полив на текущий день.'],['TryHarvest','Добавляет урожай в InventoryService; если не всё помещается, оставляет остаток на клетке.'],['ClearWitheredCrop','Удаляет увядшее растение и восстанавливает вспаханную землю.'],['OnDayChanged(event)','Проверяет полив; переводит растение на следующую стадию или увядает.']], events:'Слушает DayChangedEvent. Использует FarmTileVisuals для отображения и InventoryService для предметов.', note:'Состояние культур хранится в памяти. После перезапуска сцены сохранение фермы не восстановится, пока не появится система сохранений.'},
    {name:'FarmTileVisuals', type:'MonoBehaviour · визуал фермы', module:'farm', path:'Assets/_Game/Scripts/Farming/FarmTileVisuals.cs', summary:'Ставит обычный/вспаханный Tile, создаёт runtime Tile из Sprite стадии культуры и показывает затемнение политой клетки через оверлей.', where:'На FarmTilemap вместе с основным Tilemap.', must:'Initialize получает основной Tilemap, Tilled Tile и оттенок. Под тем же Grid нужен sibling Tilemap с точным именем WaterOverlayTilemap; у него материал, поддерживающий Sprite tint/alpha.', optional:'Sorting Order overlay выставляется немного выше FarmTilemap автоматически.', methods:[['Awake()','Находит основной Tilemap и WaterOverlayTilemap.'],['Initialize(tilemap, soilTile, wetTint)','Получает данные из FarmTilemapController.'],['FindWaterOverlay()','Находит sibling WaterOverlayTilemap и настраивает его сортировку.'],['HasTile(cell)','Проверяет клетку.'],['SetTilled / SetTile','Меняет Tile и сначала сбрасывает цвет/оверлей.'],['SetSprite(cell, sprite)','Создаёт или берёт Tile для Sprite и ставит его в клетку.'],['ShowWatered(cell)','Копирует sprite клетки в overlay и затемняет его.'],['ResetColor(cell)','Сбрасывает цвет Tile и удаляет overlay для клетки.'],['GetRuntimeTile / GetOverlayTile','Кэширует runtime Tile, чтобы не создавать его повторно.'],['OnDestroy()','Очищает созданные runtime Tile и overlay.']], events:'Вызывается FarmCropSystem; напрямую события не публикует.', note:'Не рисуй тайлы в WaterOverlayTilemap вручную. Не назначай туда материал смешивания текстур, который игнорирует прозрачность/цвет спрайта.'},
    {name:'FarmTargetPreview', type:'MonoBehaviour · подсветка клетки', module:'farm', path:'Assets/_Game/Scripts/Farming/FarmTargetPreview.cs', summary:'Показывает и скрывает SpriteRenderer-маркер на центре клетки, с которой игрок сможет взаимодействовать.', where:'На FarmTilemap; сам SpriteRenderer — отдельный дочерний объект preview, назначенный контроллеру.', must:'Initialize получает Tilemap и SpriteRenderer.', optional:'Можно заменить спрайт рамки, цвет и Sorting Order, не меняя логику.', methods:[['Initialize(tilemap, renderer)','Сохраняет Renderer, подгоняет размер маркера и скрывает его.'],['ShowAt(worldPosition)','Перемещает маркер и включает Renderer.'],['Hide()','Выключает Renderer.']], events:'Контроллер вычисляет целевую клетку и вызывает ShowAt/Hide.', note:'Подсветка должна смотреть на ту же InteractionPosition и FacingDirection, что и реальное действие.'},
    {name:'IInteractable / IDirectionalInteractor', type:'общие интерфейсы', module:'player', path:'Assets/_Game/Scripts/Interaction/', summary:'Два простых договора: какие объекты можно активировать и как узнать направление игрока.', where:'IInteractable у станций и FarmTilemapController; IDirectionalInteractor реализует PlayerController2D.', must:'Collider2D рядом с объектом; совместимая реализация метода Interact(GameObject).', optional:'Интерфейсы можно использовать на будущих NPC и новых устройствах.', methods:[['IInteractable.Interact(interactor)','Выполняет действие объекта.'],['IDirectionalInteractor.FacingDirection','Возвращает последнее направление взаимодействия.']], events:'Событий не имеют.', note:'Создавай новую станцию через этот интерфейс вместо ещё одного глобального обработчика триггеров.'},
    {name:'CarvingRecipe', type:'ScriptableObject · данные рецепта', module:'data', path:'Assets/_Game/Scripts/Carving/CarvingRecipe.cs', summary:'Хранит входной предмет/количество и выходной предмет/количество для вырезания тыквы.', where:'Ассет в Assets/_Game/Data/Carving/.', must:'Input Item, Input Amount, Output Item, Output Amount.', optional:'Новый модуль вырезания пока отложен по решению команды.', methods:[['CreateAssetMenu','Создаёт Recipe asset.'],['InputItem / InputAmount','Входные ресурсы.'],['OutputItem / OutputAmount','Результат обработки.']], events:'Пока не включён в игровой цикл.', note:'Не считать модуль вырезания готовым только потому, что есть ассет рецепта.'},
    {name:'DemandOption', type:'serializable class · вариант заказа', module:'data', path:'Assets/_Game/Scripts/Orders/DemandSourceDefinition.cs', summary:'Один вариант спроса: какой предмет, какой диапазон количества и награда за единицу.', where:'В массиве Possible Orders внутри DemandSourceDefinition.', must:'Item, Min Quantity, Max Quantity, Reward Per Item.', optional:'У одного бизнеса может быть несколько вариантов заказа.', methods:[['Item','Какой предмет требуется.'],['MinQuantity / MaxQuantity','Случайный диапазон количества.'],['RewardPerItem','Оплата за одну единицу.']], events:'Читается DailyOrderService.', note:'Quantity рандомится внутри указанного диапазона каждый раз, когда источник выбирает этот вариант.'},
    {name:'DemandSourceDefinition', type:'ScriptableObject · источник спроса', module:'data', path:'Assets/_Game/Scripts/Orders/DemandSourceDefinition.cs', summary:'Описание кафе, ресторана или магазина: ID, название, шанс создать заказ и список вариантов спроса.', where:'Ассет в Assets/_Game/Data/Orders/; отдельный для каждого бизнеса.', must:'Уникальный SourceId, DisplayName, DailyOrderChance и PossibleOrders.', optional:'Можно выставить шанс ниже 1, чтобы у бизнеса иногда не было заказа.', methods:[['CreateAssetMenu','Создаёт Demand Source asset.'],['SourceId / DisplayName','Постоянный ID для связи со зданием и отображаемое имя.'],['DailyOrderChance','Вероятность сформировать заказ сегодня.'],['PossibleOrders','Список вариантов спроса.']], events:'Читается DailyOrderService и назначается SalesSourceStation.', note:'Не дублируй один SourceId в разных ассетах.'},
    {name:'DailyOrderDisplayData', type:'readonly struct · данные заказа для UI', module:'events', path:'Assets/_Game/Scripts/Orders/OrderEvents.cs', summary:'Снимок одного заказа для списка на HUD.', where:'Создаётся DailyOrderService при формировании обновления.', must:'SourceId, SourceName, Item, Quantity, RewardPerItem, IsCompleted.', optional:'HUDDisplayBridge выводит список простым текстом.', methods:[['DailyOrderDisplayData(...)','Создаёт один пункт списка заказа.']], events:'Входит в DailyOrdersChangedEvent.', note:'Это данные для отображения, а не объект, который нужно ставить в Hierarchy.'},
    {name:'DailyOrdersChangedEvent', type:'readonly struct · обновление заказов', module:'events', path:'Assets/_Game/Scripts/Orders/OrderEvents.cs', summary:'Передаёт новый день, сколько заказов выполнено, общее число, можно ли показывать список, и список заказов.', where:'Публикуется DailyOrderService.', must:'Day, CompletedCount, AvailableCount, IsVisible, Orders.', optional:'HUDDisplayBridge и SalesSourceStation слушают обновление.', methods:[['DailyOrdersChangedEvent(...)','Создаёт снимок текущих заказов.']], events:'GameEvents.', note:'ActiveOrders и OrderProgress должны появляться на HUD только после чтения дневного письма.'},
    {name:'DailyOrderService', type:'MonoBehaviour · генератор и сдача заказов', module:'mailorders', path:'Assets/_Game/Scripts/Orders/DailyOrderService.cs', summary:'Каждый день случайно выбирает заказ для каждого DemandSourceDefinition, отправляет письмо и принимает доставку у правильного бизнеса.', where:'На GameSystems. Массив Sources настраивается в Inspector.', must:'GameServices, DayCycleService, MailboxService, InventoryService, WalletService, DemandSourceDefinition[] Sources.', optional:'SalesSourceStation на каждом здании и HUDDisplayBridge для отображения.', methods:[['OnEnable()/OnDisable()','Регистрируется, подписывается на DayChangedEvent и MailReadEvent.'],['Start()','Создаёт заказы для стартового дня, если событие дня было до подписки.'],['OnDayChanged(event)','Запускает генерацию нового дня.'],['OnMailRead(event)','Разрешает показывать заказы после чтения соответствующего письма.'],['GenerateForDayIfNeeded(day)','Сбрасывает старые заказы и для каждого источника бросает шанс.'],['SendDailyOrdersMail()','Создаёт MailMessageData с выбранными заказами; список пока скрыт.'],['HasActiveOrder(sourceId)','Возвращает true, если у бизнеса есть видимый незавершённый заказ.'],['TryFulfill(sourceId)','Проверяет предметы, удаляет нужное количество и начисляет награду.'],['SafeReward(...)','Защищает расчёт награды от слишком большого значения.'],['PublishOrdersChanged()','Публикует снимок заказов и прогресс X/Y.']], events:'Слушает DayChangedEvent и MailReadEvent; отправляет DailyOrdersChangedEvent; получает предметы через InventoryService и выдаёт деньги через WalletService.', note:'Один источник выдаёт максимум один заказ за день или не выдаёт его. Просроченные заказы не переносятся; сохранения пока нет.'},
    {name:'SalesSourceStation', type:'MonoBehaviour · сдача заказу', module:'mailorders', path:'Assets/_Game/Scripts/Orders/SalesSourceStation.cs', summary:'На конкретном бизнесе принимает заказ от игрока и показывает индикатор, если есть незавершённый заказ этого источника.', where:'На здании Cafe / Restaurant / Grocery Store.', must:'Collider2D, DemandSourceDefinition, поле Active Order Indicator (дочерний объект со SpriteRenderer).', optional:'Индикатор можно настроить отдельным спрайтом/позициями на prefab здания.', methods:[['OnEnable()/Start()/OnDisable()','Подписывается на изменения заказов и обновляет состояние индикатора.'],['Interact(interactor)','Вызывает DailyOrderService.TryFulfill(SourceId).'],['OnOrdersChanged(event)','Обновляет индикатор при изменении списка.'],['RefreshIndicator()','Показывает спрайт только если есть активный заказ.']], events:'Слушает DailyOrdersChangedEvent.', note:'В поле Source назначай ассет DemandSourceDefinition, а не объект другой станции.'},
    {name:'MailMessageData', type:'readonly struct · письмо', module:'events', path:'Assets/_Game/Scripts/Mail/MailboxEvents.cs', summary:'Содержимое письма: уникальный ID, день, тема и текст.', where:'Создаётся MailboxService / DailyOrderService.', must:'Id, Day, Subject, Body.', optional:'Тема и body в игре на английском.', methods:[['MailMessageData(id, day, subject, body)','Создаёт письмо.']], events:'Передаётся в MailReceivedEvent и MailReadEvent.', note:'Для ежедневных заказов ID имеет вид daily-orders-N.'},
    {name:'MailReceivedEvent', type:'readonly struct · новое письмо', module:'events', path:'Assets/_Game/Scripts/Mail/MailboxEvents.cs', summary:'Оповещает, что письмо добавлено в почту.', where:'Публикуется MailboxService.Receive().', must:'Message — MailMessageData.', optional:'MailboxStation зажигает MailIndicator.', methods:[['MailReceivedEvent(message)','Создаёт событие нового письма.']], events:'Слушает MailboxStation.', note:'Сам по себе не показывает письмо на HUD: игрок должен подойти к почтовому ящику.'},
    {name:'MailReadEvent', type:'readonly struct · прочитанное письмо', module:'events', path:'Assets/_Game/Scripts/Mail/MailboxEvents.cs', summary:'Оповещает, что игрок нажал Read и письмо отмечено прочитанным.', where:'Публикуется MailboxService.MarkRead().', must:'Message — MailMessageData.', optional:'DailyOrderService открывает дневные заказы только после прочтения письма.', methods:[['MailReadEvent(message)','Создаёт событие прочтения.']], events:'Слушает DailyOrderService и MailboxStation.', note:'Если прочитали письмо с заказами, HUD показывает список и активные точки сбыта получают индикатор.'},
    {name:'MailboxOpenRequestedEvent', type:'readonly struct · открытие почты', module:'events', path:'Assets/_Game/Scripts/Mail/MailboxEvents.cs', summary:'Запрос от почтового ящика открыть панель письма.', where:'Публикуется MailboxStation при взаимодействии.', must:'Отдельных полей нет.', optional:'MailboxPanelController слушает событие.', methods:[['MailboxOpenRequestedEvent()','Пустой сигнал «попробовать открыть письмо».']], events:'GameEvents.', note:'Панель открывает следующее непрочитанное письмо через MailboxService.'},
    {name:'MailboxService', type:'MonoBehaviour · список почты', module:'mailorders', path:'Assets/_Game/Scripts/Mail/MailboxService.cs', summary:'Хранит письма текущего сеанса, отдаёт следующее непрочитанное и отмечает письма прочитанными.', where:'На GameSystems.', must:'GameServices, MailMessageData и Mailbox events.', optional:'MailboxStation и MailboxPanelController пользуются им через GameServices.', methods:[['OnEnable()/OnDisable()','Регистрируется/удаляется из реестра.'],['Receive(message)','Добавляет письмо, не допуская повтор одного ID.'],['TryGetNextUnread(out message)','Выбирает актуальное непрочитанное письмо.'],['MarkRead(messageId)','Помечает письмо прочитанным и публикует MailReadEvent.'],['HasUnreadMessages / IsDailyOrderMail','Проверка состояния почты и писем daily-orders.']], events:'Публикует MailReceivedEvent и MailReadEvent.', note:'У пользователя оставлена одна кнопка Read: после чтения окно закрывается. Старое письмо о ежедневных заказах не должно удерживать индикатор нового дня.'},
    {name:'MailboxStation', type:'MonoBehaviour · объект почтового ящика', module:'mailorders', path:'Assets/_Game/Scripts/Mail/MailboxStation.cs', summary:'Открывает почту по Space и управляет видимостью дочернего MailIndicator.', where:'На PF_Mailbox вместе с Collider2D.', must:'MailboxService доступен через GameServices; поле Unread Indicator должно указывать на дочерний MailIndicator в Prefab Mode.', optional:'Спрайт/цвет индикатора настраивается визуально.', methods:[['OnEnable()/Start()/OnDisable()','Подписывается на MailReceivedEvent и MailReadEvent, обновляет состояние.'],['Interact(interactor)','Публикует MailboxOpenRequestedEvent.'],['OnMailChanged(event)','Реагирует на новое/прочитанное письмо.'],['RefreshIndicator()','Включает индикатор, когда есть непрочитанная почта.']], events:'Слушает MailReceivedEvent и MailReadEvent; открывает MailboxPanelController через событие.', note:'В поле Unread Indicator перетаскивай именно дочерний объект, не Prefab Asset из Project.'},
    {name:'MailboxPanelController', type:'MonoBehaviour · окно чтения письма', module:'ui', path:'Assets/_Game/Scripts/Mail/MailboxPanelController.cs', summary:'Берёт следующее непрочитанное письмо, показывает тему/текст и закрывает окно после успешного чтения.', where:'На активном GameHUD, не на выключаемом MailboxPanel.', must:'Panel Root, Subject Text, Body Text, Read Button; MailboxService в GameServices.', optional:'Текущая версия без Cancel/Close для непрочитанного письма — пользователь отказался от этого поведения из-за рассинхронизации дней.', methods:[['Awake()','Скрывает панель на старте.'],['OnEnable()/OnDisable()','Подписывается на MailboxOpenRequestedEvent, подключает кнопку Read и снимает блокировку при выключении.'],['OnMailboxOpenRequested(event)','Получает следующее непрочитанное письмо, заполняет TMP и открывает панель.'],['ReadCurrentMessage()','Вызывает MailboxService.MarkRead; закрывает окно только при успехе.'],['ClosePanel()','Закрывает окно и снимает GameplayInputGate.']], events:'Слушает MailboxOpenRequestedEvent; MarkRead приводит к MailReadEvent.', note:'Игрок должен подойти к ящику — уведомление не всплывает прямо на HUD.'},
    {name:'StorageContainer', type:'MonoBehaviour · содержимое здания', module:'storage', path:'Assets/_Game/Scripts/Storage/StorageContainer.cs', summary:'Отдельный инвентарь самого здания. Вместимость в Inspector; у каждого здания своя коллекция слотов.', where:'На prefab хранилища; вместе со StorageStation на здании.', must:'Display Name, Slot Count; StorageSlot[] и события StorageChangedEvent.', optional:'Большая StoragePanel с ScrollRect.', methods:[['Awake()/InitializeSlots()','Создаёт заданное количество пустых слотов.'],['GetSnapshot()','Возвращает снимок всех слотов для UI.'],['TryGetSlotContents(index, out item, out quantity)','Читает конкретный слот.'],['CanAcceptAtSlot(...)','Проверяет, помещается ли предмет в заданный слот.'],['TryAddToSlot / TryTakeFromSlot','Добавляет в слот или забирает его содержимое.'],['SwapSlots(first, second)','Меняет содержимое двух слотов.'],['PublishChanged()','Публикует StorageChangedEvent с полным снимком.']], events:'Публикует StorageChangedEvent и предоставляет StorageOpenedEvent через станцию.', note:'Хранилище не покупается и не связано с Wallet. Данные переживают закрытие окна, но не перезапуск сцены/игры без системы сохранения.'},
    {name:'StorageSlot', type:'класс данных', module:'storage', path:'Assets/_Game/Scripts/Storage/StorageContainer.cs', summary:'Одна слот-ячейка в хранилище: Item и Quantity.', where:'Создаётся StorageContainer.', must:'Нет компонентов Unity.', optional:'UI использует StorageSlotData snapshot.', methods:[['Set(item, quantity)','Записывает содержимое.'],['Clear()','Очищает ячейку.']], events:'Нет.', note:'Не меняй напрямую из UI; используй методы StorageContainer.'},
    {name:'StorageStation', type:'MonoBehaviour · открытие склада', module:'storage', path:'Assets/_Game/Scripts/Storage/StorageStation.cs', summary:'При взаимодействии публикует событие открытия своего StorageContainer.', where:'На здании хранилища рядом с StorageContainer.', must:'Collider2D; StorageContainer на этом же объекте; общий IInteractable.', optional:'DisplayName на StorageContainer называет окно, например Harvest Storage.', methods:[['Awake()','Находит свой StorageContainer.'],['Interact(interactor)','Публикует StorageOpenedEvent, передавая именно своё хранилище.']], events:'StoragePanelController слушает StorageOpenedEvent.', note:'Для второго склада достаточно второго здания с другим StorageContainer — контент разделён.'},
    {name:'StorageOpenedEvent', type:'readonly struct · открыть склад', module:'events', path:'Assets/_Game/Scripts/Storage/StorageEvents.cs', summary:'Передаёт ссылку на тот StorageContainer, который игрок открыл.', where:'Публикуется StorageStation.', must:'Container.', optional:'StoragePanelController строит карточки для переданного контейнера.', methods:[['StorageOpenedEvent(container)','Создаёт запрос на открытие конкретного здания.']], events:'GameEvents.', note:'Нужно, чтобы один и тот же UI обслуживал много разных складов.'},
    {name:'StorageSlotData', type:'readonly struct · снимок слота склада', module:'events', path:'Assets/_Game/Scripts/Storage/StorageEvents.cs', summary:'Представляет Item и Quantity одного слота для UI.', where:'Создаётся StorageContainer.GetSnapshot().', must:'Item, Quantity, IsEmpty.', optional:'StorageSlotCardView.', methods:[['StorageSlotData(item, quantity)','Создаёт снимок слота.']], events:'Входит в массив StorageChangedEvent.', note:'Снимок не равен живому StorageSlot.'},
    {name:'StorageChangedEvent', type:'readonly struct · обновление склада', module:'events', path:'Assets/_Game/Scripts/Storage/StorageEvents.cs', summary:'Передаёт хранилище и весь снимок его слотов после переноса/обмена.', where:'Публикуется StorageContainer.', must:'Container и Slots.', optional:'StoragePanelController обновляет карточки.', methods:[['StorageChangedEvent(container, slots)','Создаёт событие с новым содержимым.']], events:'GameEvents.', note:'Не нужно вручную обновлять UI после каждой операции — контейнер публикует обновление.'},
    {name:'StoragePanelController', type:'MonoBehaviour · окно хранилища', module:'storage', path:'Assets/_Game/Scripts/UI/StoragePanelController.cs', summary:'Открывает окно нужного хранилища, строит карточки, обрабатывает переносы и закрывает окно.', where:'На активном GameHUD, не на выключаемой StoragePanel.', must:'Panel Root, Title, Close Button, Card Root, Card Prefab; ScrollRect/ViewPort/Content; EventSystem.', optional:'MessageText для ошибок и статуса; GridLayoutGroup + ContentSizeFitter; вертикальный Scrollbar.', methods:[['OnEnable()/OnDisable()','Подписывается на StorageOpenedEvent и StorageChangedEvent, подключает Close.'],['OnStorageOpened(event)','Запоминает контейнер, блокирует управление, показывает окно и карточки.'],['OnStorageChanged(event)','Обновляет UI, только если событие относится к открытому контейнеру.'],['RefreshCards()/EnsureCardCount()','Обновляет/создаёт необходимое количество карточек.'],['TransferFromPlayer(playerIndex, storageIndex)','Переносит предмет из слота игрока в склад.'],['TransferToPlayer(storageIndex, playerIndex)','Переносит предмет из склада в инвентарь игрока.'],['SwapStorageSlots(first, second)','Меняет местами слоты текущего склада.'],['SetMessage(message)','Показывает результат операции.'],['Close()','Закрывает окно и снимает блокировку ввода.']], events:'Слушает StorageOpenedEvent/StorageChangedEvent; вызывает InventoryService и StorageContainer через методы.', note:'Для перетаскивания в UI нужен GraphicRaycaster на Canvas и EventSystem. Scrollbar связан с ScrollRect, не с карточками.'},
    {name:'StorageSlotCardView', type:'MonoBehaviour · карточка склада', module:'storage', path:'Assets/_Game/Scripts/UI/StorageSlotCardView.cs', summary:'Показывает слот хранилища, создаёт drag ghost, поддерживает перенос из игрока и перестановку в складе.', where:'На PF_StorageSlotCard.', must:'Image, TMP labels, LayoutElement; StoragePanelController назначает поля.', optional:'Иконка предмета необязательна; наличие количества показывается текстом.', methods:[['Awake()/Bind(...)','Получает компоненты и наполняет карточку.'],['OnBeginDrag / OnDrag / OnEndDrag','Создаёт/двигает/удаляет визуальный призрак предмета.'],['OnDrop(event)','Если это карточка игрока — переносит предмет; если карточка этого же склада — меняет местами.'],['TransferToPlayer(playerSlotIndex)','Запрашивает перенос в указанный слот игрока.'],['UpdateGhostPosition()','Двигает призрак во время drag.'],['OnDisable()','Удаляет временный объект перетаскивания.']], events:'Вызывает методы StoragePanelController.', note:'В ScrollRect используй нормальные Viewport + RectMask2D + Content; сам scrollbar должен быть назначен в ScrollRect.'},
    {name:'StorageSlotCardView / InventorySlotCardView', type:'UI · drag & drop', module:'ui', path:'Assets/_Game/Scripts/UI/StorageSlotCardView.cs и InventorySlotCardView.cs', summary:'Две разные карточки: одна принадлежит хранилищу, другая — инвентарю игрока. Они обмениваются переносами через контроллеры.', where:'На соответствующих UI prefabs.', must:'EventSystem, GraphicRaycaster, Raycast Target на корневом изображении.', optional:'Иконка и декоративная рамка.', methods:[['OnBeginDrag / OnDrag / OnEndDrag','Рисуют drag ghost и отслеживают перемещение.'],['OnDrop','Распознают тип второй карточки и вызывают нужный transfer/swap.']], events:'StorageChangedEvent и InventoryLayoutChangedEvent обновляют данные после операции.', note:'Не вставляй прямую логику AddItem/RemoveItem в карточку; она должна передавать запрос контроллеру.'},
    {name:'TestInteractable', type:'тестовый компонент', module:'test', path:'Assets/_Game/Scripts/Interaction/TestInteractable.cs', summary:'Временный объект для проверки, что Space находит IInteractable и вызывает Interact().', where:'На тестовом квадрате в Sandbox/Tutorial, не в production prefab.', must:'Collider2D.', optional:'Удалить со сцены после прохождения начальной проверки.', methods:[['Interact(interactor)','Выводит в Console, кто взаимодействовал с объектом.']], events:'Нет.', note:'Это тест, а не часть игрового цикла.'},
    {name:'DayAdvanceInteractable', type:'тестовый компонент', module:'test', path:'Assets/_Game/Scripts/Core/DayAdvanceInteractable.cs', summary:'Временная тестовая кнопка-квадрат, которая вызывает AdvanceDay по Space.', where:'Только в Tutorial для тестирования роста культур и заказов.', must:'Collider2D, DayCycleService в GameSystems.', optional:'Заменить позже реальной механикой окончания дня.', methods:[['Interact(interactor)','Находит DayCycleService через GameServices и вызывает AdvanceDay().']], events:'Приводит к DayChangedEvent.', note:'Не оставляй финальному игроку тестовый квадрат, если у дня появится полноценная система сна/завершения дня.'},
    {name:'Legacy — старые менеджеры', type:'пакет старой версии', module:'legacy', path:'ScriptsZIP.zip / Scripts/', summary:'Старый набор скриптов, который был передан в исходном архиве. Некоторые файлы дублируют обязанности новой архитектуры.', where:'В исходной папке Scripts/, не в новой папке Assets/_Game/.', must:'Не добавляй их на новые prefab одновременно с новыми классами.', optional:'Сохраняй для старых сцен и референса до полной миграции.', methods:[['GameManager.cs','Старая совмещённая логика игры — заменяется отдельными сервисами.'],['TriggerController.cs','Старые триггеры — новые объекты используют IInteractable.'],['PlayerMovement.cs','Старое движение — используем PlayerController2D.'],['InventoryManager.cs / InventoryRenderer.cs / InvItem.cs','Старый инвентарь — используем InventoryService и карточный UI.'],['PickUpItem.cs / Plant.cs','Старые подбор и растения — используем PickupItem и FarmCropSystem.'],['PostManager.cs / AnoucmentBoardManager.cs / TodayDeliverPrefabScript.cs','Старые объявления/доставка — используем DailyOrderService и Mailbox.'],['BuyPrefabScript.cs / SellPrefabScript.cs / Sell.cs','Старые покупки/продажи — используем ShopService.'],['CarvingManager.cs / PumpkinInvButtonScript.cs / OrnamentsPrefabButtonClick.cs','Старая логика украшения/вырезания — пока отложена.'],['CartFollow.cs / CameraFollow.cs','Старые follow-компоненты — новые CartFollower и CameraFollow2D.'],['Dialogs/Dialog.cs / DialogRenderer.cs / Npc.cs','Старые диалоги/NPC — ещё не перенесены.']], events:'Не часть новой схемы GameEvents.', note:'Не удаляй старые файлы массово — старые сцены и prefab могут на них ссылаться.'}
  ];

  // The scripts below are useful catalog cards for event types and panels referenced throughout the system.
  scripts.push(
    {name:'ShopProductType', type:'enum · вид товара', module:'data', path:'Assets/_Game/Scripts/Shop/ShopProductDefinition.cs', summary:'Разделяет товар на обычный предмет, рюкзак или тележку.', where:'Поле Product Type в ShopProductDefinition.', must:'Item, BackpackUpgrade, CartUpgrade.', optional:'ShopService выбирает ветку покупки по типу.', methods:[['Item','Покупка/продажа реального ItemDefinition.'],['BackpackUpgrade','Добавляет группу слотов Backpack.'],['CartUpgrade','Создаёт Cart и добавляет группу Cart.']], events:'Читается ShopService.', note:'Рюкзак и тележка не занимают обычный слот предмета.'},
    {name:'MailIndicator / ActiveOrderIndicator', type:'дочерние визуальные объекты', module:'mailorders', path:'Настраиваются в prefab здания, скрипт отдельный не нужен', summary:'Спрайты-индикаторы у почтового ящика и зданий с активным заказом.', where:'MailIndicator — ребёнок Mailbox; ActiveOrderIndicator — ребёнок здания с SalesSourceStation.', must:'SpriteRenderer, назначенный дочерний объект в Inspector соответствующего station.', optional:'Положение по Y, Sorting Layer, Order in Layer и спрайт настраиваются в prefab.', methods:[['SetActive(bool)','Station включает/выключает объект на основе состояния почты или заказа.']], events:'MailboxStation реагирует на MailReceived/MailRead; SalesSourceStation — на DailyOrdersChangedEvent.', note:'В поле нужно перетащить child object из Prefab Mode, а не Prefab Asset из Project.'}
  );

  const htmlEscape = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const inlineCode = (text) => htmlEscape(text).replace(/`([^`]+)`/g, '<code>$1</code>');
  const scriptGrid = document.getElementById('scriptGrid');
  const searchInput = document.getElementById('scriptSearch');
  const moduleFilter = document.getElementById('moduleFilter');
  const resultsText = document.getElementById('resultsText');
  const scriptCount = document.getElementById('scriptCount');
  const emptyResults = document.getElementById('emptyResults');
  let activeModule = 'all';

  function renderScripts() {
    const query = (searchInput?.value || '').trim().toLocaleLowerCase('ru');
    const filter = moduleFilter?.value || activeModule;
    const filtered = scripts.filter(item => {
      const moduleMatch = filter === 'all' || item.module === filter;
      const searchable = [item.name, item.type, moduleNames[item.module], item.path, item.summary, item.where, item.must, item.optional, item.events, item.note, ...(item.methods || []).flat()].join(' ').toLocaleLowerCase('ru');
      return moduleMatch && searchable.includes(query);
    });

    scriptCount.textContent = `${filtered.length} ${plural(filtered.length, 'КЛАСС', 'КЛАССА', 'КЛАССОВ')}`;
    resultsText.textContent = query || filter !== 'all' ? `Найдено: ${filtered.length}` : `Показаны все карточки (${filtered.length})`;
    emptyResults.hidden = filtered.length !== 0;
    scriptGrid.innerHTML = filtered.map((item, idx) => {
      const methodHtml = (item.methods || []).map(([name, desc]) => `<li><code>${htmlEscape(name)}</code> — ${htmlEscape(desc)}</li>`).join('');
      const badge = item.module === 'legacy' ? 'СТАРОЕ / НЕ ПОДКЛЮЧАТЬ' : (moduleNames[item.module] || item.module).toLocaleUpperCase('ru');
      return `<details class="script-card" id="script-${safeId(item.name)}" data-module="${item.module}">
        <summary class="script-summary">
          <div class="script-headline"><div><div class="script-name">${htmlEscape(item.name)}</div><span class="script-file">${htmlEscape(item.path)}</span></div><span class="script-badge ${item.module === 'legacy' ? 'legacy-badge' : ''}">${htmlEscape(badge)}</span></div>
          <p class="script-desc">${htmlEscape(item.summary)}</p>
          <div class="script-summary-bottom"><span>${htmlEscape(item.type)}</span><span class="method-count">${(item.methods || []).length} ${plural((item.methods || []).length,'метод','метода','методов')} <span class="script-chevron">⌄</span></span></div>
        </summary>
        <div class="script-details"><div class="script-detail-grid">
          <div class="detail-block"><h4>Куда добавлять</h4><p>${htmlEscape(item.where)}</p></div>
          <div class="detail-block"><h4>Обязательно</h4><p>${htmlEscape(item.must)}</p></div>
          <div class="detail-block"><h4>Необязательно / с чем связан</h4><p>${htmlEscape(item.optional)}</p></div>
          <div class="detail-block"><h4>Методы и свойства</h4><ul>${methodHtml}</ul></div>
          <div class="detail-block"><h4>События и связи</h4><p>${htmlEscape(item.events)}</p></div>
          <div class="detail-block"><h4>Примечание</h4><p>${htmlEscape(item.note)}</p></div>
        </div><div class="script-path-row"><code>${htmlEscape(item.path)}</code><button class="copy-path" type="button" data-copy="${htmlEscape(item.path)}">Скопировать путь</button></div></div>
      </details>`;
    }).join('');
  }

  function plural(n, one, few, many) {
    const n10 = n % 10, n100 = n % 100;
    if (n10 === 1 && n100 !== 11) return one;
    if (n10 >= 2 && n10 <= 4 && (n100 < 12 || n100 > 14)) return few;
    return many;
  }
  function safeId(value) { return String(value).replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').toLowerCase(); }

  searchInput?.addEventListener('input', renderScripts);
  moduleFilter?.addEventListener('change', () => {
    activeModule = moduleFilter.value;
    document.querySelectorAll('.chip').forEach(chip => chip.classList.toggle('active', chip.dataset.module === activeModule));
    renderScripts();
  });
  document.getElementById('clearFilters')?.addEventListener('click', () => {
    searchInput.value = ''; activeModule = 'all'; moduleFilter.value = 'all';
    document.querySelectorAll('.chip').forEach(chip => chip.classList.toggle('active', chip.dataset.module === 'all'));
    renderScripts();
  });
  document.getElementById('quickFilters')?.addEventListener('click', event => {
    const chip = event.target.closest('.chip');
    if (!chip) return;
    activeModule = chip.dataset.module;
    moduleFilter.value = activeModule;
    document.querySelectorAll('.chip').forEach(item => item.classList.toggle('active', item === chip));
    renderScripts();
    document.getElementById('scripts')?.scrollIntoView({behavior:'smooth'});
  });
  document.querySelectorAll('.module-card[data-filter-module]').forEach(card => card.addEventListener('click', () => {
    const value = card.dataset.filterModule;
    activeModule = value;
    if (moduleFilter) moduleFilter.value = value;
    if (searchInput) searchInput.value = '';
    document.querySelectorAll('.chip').forEach(chip => chip.classList.toggle('active', chip.dataset.module === value));
    renderScripts();
  }));

  document.addEventListener('click', async event => {
    const button = event.target.closest('.copy-path');
    if (!button) return;
    const text = button.dataset.copy || '';
    try {
      await navigator.clipboard.writeText(text);
      button.textContent = 'Скопировано ✓';
    } catch (error) {
      const helper = document.createElement('textarea');
      helper.value = text; document.body.appendChild(helper); helper.select();
      try { document.execCommand('copy'); button.textContent = 'Скопировано ✓'; }
      catch { button.textContent = 'Не скопировано'; }
      helper.remove();
    }
    setTimeout(() => { button.textContent = 'Скопировать путь'; }, 1800);
  });

  const diagramDescriptions = {
    core: ['Общие механизмы', 'GameServices даёт доступ к зарегистрированным сервисам. DayCycleService считает дни. GameEvents разносит сообщения, а GameplayInputGate временно останавливает управление во время открытых окон.'],
    events: ['GameEvents и события', 'GameEvents — общий канал сообщений. Например, DayChangedEvent сообщает о новом дне, а InventoryLayoutChangedEvent сообщает UI, как теперь выглядят слоты. Сами события только передают данные.'],
    input: ['GameplayInputGate', 'Флажок блокировки управления. Окно включает его при открытии и снимает при закрытии.'],
    data: ['Настройки-ассеты', 'ItemDefinition, CropDefinition, ShopProductDefinition, ShopCatalog и DemandSourceDefinition хранят настройки. Их создают в Project через Create и заполняют в Inspector.'],
    player: ['Игрок и взаимодействие', 'PlayerController2D двигает персонажа. PlayerInteractor находит ближайший IInteractable. IDirectionalInteractor отдаёт направление, нужное ферме для выбора клетки.'],
    farm: ['Ферма на Tilemap', 'FarmTilemapController получает действие игрока, FarmCropSystem хранит состояние культур, FarmTileVisuals рисует стадии и полив, FarmTargetPreview подсвечивает выбранную клетку.'],
    shops: ['Магазин и тележка', 'ShopStation открывает каталог, ShopService проверяет сделку, WalletService меняет баланс, а CartService управляет тележкой и бонусом вместимости.'],
    mailorders: ['Почта и заказы', 'DailyOrderService создаёт дневной спрос, MailboxService хранит письма, MailboxStation показывает индикатор, SalesSourceStation принимает заказ. На HUD заказы выводятся после прочтения письма.'],
    storage: ['Хранилище', 'StorageContainer хранит предметы конкретного здания. StorageStation открывает контейнер, StoragePanelController показывает карточки и управляет переносом.'],
    hud: ['HUD и окна', 'HUDDisplayBridge превращает игровые события в текстовые значения. HUDPresenter передаёт их в HUDTextBinding. Отдельные контроллеры управляют окном магазина, почты и хранилища.'],
    inventoryui: ['Инвентарь и карточки', 'InventoryService хранит слоты. InventoryHUDController отображает их, а InventorySlotCardView отвечает за карточку и перетаскивание. Данные остаются в сервисе.']
  };
  const diagramDetail = document.getElementById('diagramDetail');
  document.querySelectorAll('.architecture-module').forEach(node => {
    node.addEventListener('click', () => {
      document.querySelectorAll('.architecture-module').forEach(other => other.classList.toggle('selected', other === node));
      const id = node.dataset.jump;
      const description = diagramDescriptions[id] || ['Модуль', 'Подробности можно найти в справочнике скриптов ниже.'];
      if (diagramDetail) diagramDetail.innerHTML = `<strong>${htmlEscape(description[0])}</strong><p>${htmlEscape(description[1])}</p>`;
      const value = node.dataset.filterModule || 'all';
      activeModule = value;
      if (moduleFilter) moduleFilter.value = value;
      if (searchInput) searchInput.value = '';
      document.querySelectorAll('.chip').forEach(chip => chip.classList.toggle('active', chip.dataset.module === value));
      renderScripts();
      document.getElementById('scripts')?.scrollIntoView({behavior:'smooth'});
    });
  });
  document.getElementById('diagramReset')?.addEventListener('click', () => {
    document.querySelectorAll('.architecture-module').forEach(node => node.classList.remove('selected'));
    if (diagramDetail) diagramDetail.innerHTML = '<strong>Главные связующие скрипты</strong><p><code>GameServices</code> находит сервисы. <code>GameEvents</code> рассылает сообщения. <code>IInteractable</code> связывает игрока с объектами мира. <code>GameplayInputGate</code> блокирует управление, пока открыта панель.</p>';
  });

  // Build checklist persists when the browser permits localStorage for file://.
  const safeStorageGet = (key) => { try { return localStorage.getItem(key); } catch (_) { return null; } };
  const safeStorageSet = (key, value) => { try { localStorage.setItem(key, value); } catch (_) { /* checklist still works for this page session */ } };
  const safeStorageRemove = (key) => { try { localStorage.removeItem(key); } catch (_) { /* ignored */ } };
  const checks = [...document.querySelectorAll('[data-check]')];
  const progressBar = document.getElementById('buildProgressBar');
  const progressText = document.getElementById('buildProgressText');
  function updateBuildProgress() {
    let complete = 0;
    checks.forEach(check => {
      const saved = safeStorageGet(`guide-${check.dataset.check}`) === '1';
      check.checked = saved;
      const card = check.closest('.build-step');
      card?.classList.toggle('checked', check.checked);
      if (check.checked) complete++;
    });
    const percent = checks.length ? (complete / checks.length) * 100 : 0;
    if (progressBar) progressBar.style.width = `${percent}%`;
    if (progressText) progressText.textContent = `${complete} из ${checks.length}`;
  }
  checks.forEach(check => check.addEventListener('change', () => {
    safeStorageSet(`guide-${check.dataset.check}`, check.checked ? '1' : '0');
    updateBuildProgress();
  }));
  document.getElementById('resetBuildChecks')?.addEventListener('click', () => {
    checks.forEach(check => safeStorageRemove(`guide-${check.dataset.check}`));
    updateBuildProgress();
  });

  // Navigation state and mobile sidebar.
  const sidebar = document.getElementById('sidebar');
  document.getElementById('menuToggle')?.addEventListener('click', event => {
    const open = sidebar.classList.toggle('open');
    event.currentTarget.setAttribute('aria-expanded', String(open));
  });
  sidebar?.querySelectorAll('a').forEach(link => link.addEventListener('click', () => {
    sidebar.classList.remove('open');
    document.getElementById('menuToggle')?.setAttribute('aria-expanded','false');
    sidebar.querySelectorAll('a').forEach(item => item.classList.toggle('active', item === link));
  }));
  const backToTop = document.getElementById('backToTop');
  window.addEventListener('scroll', () => backToTop?.classList.toggle('visible', window.scrollY > 450), {passive:true});
  backToTop?.addEventListener('click', () => window.scrollTo({top:0, behavior:'smooth'}));

  renderScripts();
  updateBuildProgress();
})();
